#include <spacerad/OrbitEnvironment.h>
#include <spacerad/DeviceResponse.h>
#include <spacerad/engine/Geometry.h>
#include <QCoreApplication>
#include <iostream>
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(argc!=2)return 2;try{auto review=spacerad::loadOrbitModelJob(app.arguments()[1]);spacerad::OrbitEnvironmentService service;auto settings=spacerad::OrbitEnvironmentSettings{};settings.ephemeris="external.csv";if(service.running()||spacerad::OrbitEnvironmentSettings::fromJson(settings.toJson()).frame!="GEO")return 3;auto project=spacerad::Project::demo();spacerad::DeviceResponseTable response;response.metric="ddd";response.responseUnit="MeV_cm2_per_g";response.angularBasis="isotropic_omnidirectional";response.sourceFile={{"file_name","consumer-fixture"},{"size_bytes",0},{"sha256",std::string(64,'0')}};auto geometry=spacerad::engine::compileGeometry(project);for(const auto& v:geometry.volumes)if(v.sensitive)for(const auto& spectrum:project.spectra)response.curves.push_back({v.id,spectrum.particle,"consumer-only illustrative curve",{spectrum.energy.front(),spectrum.energy.back()},{1,1}});auto folded=spacerad::foldDeviceResponseTable(project,response);if(folded.at("rows").empty()||spacerad::deviceResponseCsv(folded).isEmpty())return 4;std::cout<<"installed-orbit: "<<review.at("samples")<<" samples; "<<review.at("duration_s")<<" s; offline verified; device-response API rows="<<folded.at("rows").size()<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
